nt main(int argc, char **argv) { (void)argc; (void)argv; if (&fk_genesis_len) { fk_gen = fk_genesis; fk_gen_len = fk_genesis_len; } long long ci = 0; while (fk_prog[ci] != 0) { if (ci >= 16777215) { printf("fkwu: baked form table exceeds emitted buffer capacity\n"); return 3; } fk_buf[ci] = fk_prog[ci]; ci = ci + 1; } fk_buf_len = ci; fk_buf[ci] = 0; fk_pos = 0; fk_parse_bad = 0; long long nf = fk_next(); if (fk_parse_bad || nf < 1 || nf > 16384) { printf("fkwu: malformed form table function count\n"); return 4; } fk_fn_count = nf; long long k = 0; while (k < nf) { fk_fn[k] = fk_next(); k = k + 1; } long long nr = fk_next(); if (fk_parse_bad || nr < 1 || nr > 524288) { printf("fkwu: malformed form table node count\n"); return 4; } fk_node_count = nr; long long r = 0; while (r < nr) { fk_node[r][0] = fk_next(); fk_node[r][1] = fk_next(); fk_node[r][2] = fk_next(); fk_node[r][3] = fk_next(); r = r + 1; } long long ns = fk_next(); if (fk_parse_bad || ns < 0) { printf("fkwu: malformed form table string count\n"); return 4; } fk_sinit(); long long si = 0; while (si < ns) { long long sl = fk_next(); if (fk_parse_bad || sl < 0) { printf("fkwu: malformed form table string length\n"); return 4; } if (fk_sp >= fk_scap_s) { fk_scap_s = fk_scap_s * 2; fk_so = realloc(fk_so, fk_scap_s * 8); fk_sl = realloc(fk_sl, fk_scap_s * 8); } while (fk_sbp + sl > fk_scap_b) { fk_scap_b = fk_scap_b * 2; fk_sb = realloc(fk_sb, fk_scap_b); } fk_so[fk_sp] = fk_sbp; fk_sl[fk_sp] = sl; long long bj = 0; while (bj < sl) { fk_sb[fk_sbp] = (char)fk_next(); fk_sbp = fk_sbp + 1; bj = bj + 1; } fk_sp = fk_sp + 1; si = si + 1; } while (fk_pos < fk_buf_len && (fk_buf[fk_pos] == 32 || fk_buf[fk_pos] == 9 || fk_buf[fk_pos] == 10 || fk_buf[fk_pos] == 13)) { fk_pos = fk_pos + 1; } if (fk_parse_bad || fk_pos != fk_buf_len) { printf("fkwu: malformed or truncated form table\n"); return 4; } fk_vs[0] = 0; fk_vsp = 1; fk_walk(fk_fn[0], 0); return 0; }
